import app from 'flarum/forum/app';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import Button from 'flarum/common/components/Button';
import LinkButton from 'flarum/common/components/LinkButton';
import Link from 'flarum/common/components/Link';
import Dropdown from 'flarum/common/components/Dropdown';
import ItemList from 'flarum/common/utils/ItemList';
import listItems from 'flarum/common/helpers/listItems';
import classList from 'flarum/common/utils/classList';
import SidebarSection from './SidebarSection';
import DraftsMenu, { showDraftsMenu } from '../features/composer/drafts/DraftsMenu';
import { FooterColorMode, FooterPaletteSelector } from '../shell/colorMode';
import { getCommunityMore, getSidebarPicks } from '../utils/sidebarPrefs';
import { forumBool, forumInt, isExtensionEnabled, t } from '../utils/settings';
import { allTags, categoriesUrl, categorySymbol, currentTag, isTagsEnabled, primaryTags, secondaryTags, sortTags, tagSymbol, tagUrl } from '../utils/tags';

/** Itens que o flarum/tags põe na navegação do IndexSidebar: aqui eles têm seções próprias. */
const TAG_NAV_KEYS = /^(tags|separator|moreTags|tag\d+)$/;

/**
 * A barra lateral do Discourse: botão "Iniciar Discussão", a seção da comunidade
 * (Tópicos, Minhas postagens, Mais…), as categorias e as etiquetas, e um
 * rodapé com o tema claro/escuro e os atalhos de teclado.
 *
 * Herda do IndexSidebar para receber de graça o que as extensões põem na
 * navegação da página inicial — Seguindo, por exemplo —, com o `active` que o
 * LinkButton já calcula.
 */
export default class CanelaSidebar extends IndexSidebar {
  view() {
    return m("div", {
      className: "CanelaSidebar-inner"
    }, m("div", {
      className: "CanelaSidebar-sections"
    }, this.sectionItems().toArray()), forumBool('canelaSidebarFooter', true) && m("div", {
      className: "CanelaSidebar-footer"
    }, this.footerItems().toArray()));
  }
  sectionItems() {
    const items = new ItemList();

    // Como no Discourse, o botão só aparece para quem está logado (o visitante
    // tem o "Entrar" do cabeçalho). O admin pode escondê-lo de vez.
    if (app.session.user && forumBool('canelaSidebarNewTopic', true)) items.add('newTopic', this.newTopicButton(), 100);
    items.add('community', m(SidebarSection, {
      name: "community"
    }, listItems(this.communitySection().toArray())), 90);
    if (isTagsEnabled() && forumBool('canelaSidebarCategories', true)) {
      const categories = this.categoryItems();
      if (!categories.isEmpty()) {
        items.add('categories', m(SidebarSection, Object.assign({
          name: "categories",
          title: t('sidebar.categories')
        }, this.editAttrs('categories')), listItems(categories.toArray())), 80);
      }
    }
    if (isTagsEnabled() && forumBool('canelaSidebarTags', true)) {
      const tags = this.tagItems();
      if (!tags.isEmpty()) {
        items.add('tags', m(SidebarSection, Object.assign({
          name: "tags",
          title: t('sidebar.tags')
        }, this.editAttrs('tags')), listItems(tags.toArray())), 70);
      }
    }
    return items;
  }

  /** O lápis de personalizar a seção, como no Discourse. */
  editAttrs(section) {
    return {
      editLabel: t(section === 'categories' ? 'sidebar.customize_categories' : 'sidebar.customize_tags'),
      onEdit: () => app.modal.show(() => import(/* webpackChunkName: 'forum/components/SidebarCustomizeModal', webpackMode: 'lazy-once' */ './SidebarCustomizeModal'), {
        section
      })
    };
  }

  /** As tags escolhidas pelo leitor para a seção, na ordem do fórum. */
  pickedTags(section) {
    const picks = getSidebarPicks(section);
    if (!picks) return null;
    const ids = new Set(picks);
    return sortTags(allTags().filter(tag => ids.has(tag.id())));
  }
  newTopicButton() {
    const tag = currentTag();
    const canStart = !app.session.user || (tag?.canStartDiscussion ? tag.canStartDiscussion() : !!app.forum.attribute('canStartDiscussion'));

    // Com rascunhos (fof/drafts), o botão vira o dividido do Discourse:
    // "✎ Novo tópico" e o "⌄" com a lista de rascunhos.
    const split = showDraftsMenu();
    return m("div", {
      className: classList('CanelaSidebar-newTopic', split && 'CanelaSidebar-newTopic--split')
    }, m(Button, {
      className: "Button Button--primary CanelaSidebar-newTopicButton",
      icon: "fas fa-pen-to-square",
      disabled: !canStart,
      onclick: () => this.newDiscussionAction().catch(() => {})
    }, t('sidebar.new_topic')), split && m(DraftsMenu, null));
  }
  communityItems() {
    const items = new ItemList();
    const user = app.session.user;
    const params = app.search.state.stickyParams();
    items.add('topics', m(LinkButton, {
      href: app.route('index', params),
      icon: "fas fa-layer-group",
      active: this.isIndexActive()
    }, t('sidebar.topics')), 100);

    // O que as outras extensões põem na navegação (Seguindo, por exemplo),
    // menos a lista de tags, que aqui tem seção própria.
    const extensionItems = this.navItems();
    extensionItems.remove('allDiscussions');
    Object.entries(extensionItems.toObject()).forEach(([key, item]) => {
      if (!TAG_NAV_KEYS.test(key)) items.add(key, item.content, item.priority);
    });
    if (user) {
      items.add('myPosts', m(LinkButton, {
        href: app.route('user.posts', {
          username: user.slug()
        }),
        icon: "far fa-user"
      }, t('sidebar.my_posts')), 60);
      if (isExtensionEnabled('flarum-messages')) {
        items.add('myMessages', m(LinkButton, {
          href: app.route('messages'),
          icon: "fas fa-inbox"
        }, t('sidebar.my_messages')), 55);
      }
      if (user.isAdmin()) {
        items.add('admin', m(LinkButton, {
          href: app.forum.attribute('adminUrl'),
          icon: "fas fa-wrench",
          external: true,
          target: "_self"
        }, t('sidebar.admin')), 50);
      }
    }
    items.add('more', this.moreDropdown(), -100);
    return items;
  }

  /**
   * A seção principal depois de todas as extensões terem posto os seus itens:
   * os que o leitor escolheu esconder vão para dentro do "Mais", e o "Mais"
   * ganha o "Personalizar" com a lista de todos eles.
   */
  communitySection() {
    const items = this.communityItems();
    const hidden = new Set(getCommunityMore());
    const entries = [];
    const moved = [];
    Object.keys(items.toObject()).forEach(key => {
      if (key === 'more') return;
      const vnode = items.get(key);
      entries.push({
        key,
        label: vnodeText(vnode) || key,
        icon: vnode?.attrs?.icon
      });

      // O item ativo nunca some: quem está na página vê onde está.
      if (hidden.has(key) && vnode?.attrs?.active !== true && vnode?.attrs?.active !== 'true') {
        moved.push(vnode);
        items.remove(key);
      }
    });
    if (items.has('more')) items.setContent('more', this.moreDropdown(moved, entries));
    return items;
  }

  /** "Tópicos" fica ativo na página inicial sem filtro de tag nem de "Seguindo". */
  isIndexActive() {
    const routeName = app.current.get('routeName');
    return routeName === 'index' && !currentTag();
  }
  moreItems() {
    const items = new ItemList();
    if (isTagsEnabled()) {
      items.add('categories', m(LinkButton, {
        href: categoriesUrl(),
        icon: "fas fa-table-cells-large"
      }, t('sidebar.all_categories')), 100);
    }
    if (app.session.user) {
      items.add('notifications', m(LinkButton, {
        href: app.route('notifications'),
        icon: "far fa-bell"
      }, t('sidebar.notifications')), 90);
      items.add('settings', m(LinkButton, {
        href: app.route('settings'),
        icon: "fas fa-gear"
      }, t('sidebar.settings')), 80);
    }
    items.add('shortcuts', m(Button, {
      icon: "far fa-keyboard",
      onclick: () => app.modal.show(() => import(/* webpackChunkName: 'forum/components/KeyboardShortcutsModal', webpackMode: 'lazy-once' */ './KeyboardShortcutsModal'))
    }, t('sidebar.keyboard_shortcuts')), 10);
    return items;
  }
  moreDropdown(moved = [], entries = []) {
    const more = this.moreItems();
    if (entries.length) {
      more.add('customizeCommunity', m(Button, {
        icon: "fas fa-pencil",
        onclick: () => app.modal.show(() => import(/* webpackChunkName: 'forum/components/CommunityCustomizeModal', webpackMode: 'lazy-once' */ './CommunityCustomizeModal'), {
          entries,
          onsave: () => m.redraw()
        })
      }, t('sidebar.customize_community')), 5);
    }
    return m(Dropdown, {
      className: "CanelaSidebar-more",
      buttonClassName: "CanelaSidebar-moreButton",
      icon: "fas fa-ellipsis-vertical",
      label: t('sidebar.more'),
      caretIcon: null,
      accessibleToggleLabel: t('sidebar.more'),
      onshow: () => placeMoreMenu()
    }, [...moved, ...(moved.length ? [m("li", {
      className: "Dropdown-separator"
    })] : []), ...more.toArray()]);
  }
  categoryItems() {
    const items = new ItemList();
    const active = currentTag();
    const activeRoot = active && active.isChild() ? active.parent() : active;
    (this.pickedTags('categories') ?? primaryTags()).forEach((tag, index) => {
      items.add(`category${tag.id()}`, this.tagLink(tag, categorySymbol(tag, 'CanelaSidebar-linkIcon'), activeRoot === tag), 100 - index);
    });
    items.add('allCategories', m(LinkButton, {
      className: "CanelaSidebar-link--all",
      href: categoriesUrl(),
      icon: "fas fa-list"
    }, t('sidebar.all_categories')), -100);
    return items;
  }
  tagItems() {
    const items = new ItemList();
    const active = currentTag();
    const limit = forumInt('canelaSidebarTagsLimit', 6);
    const picked = this.pickedTags('tags');
    const tags = picked ?? secondaryTags().slice(0, limit);
    tags.forEach((tag, index) => {
      items.add(`tag${tag.id()}`, this.tagLink(tag, tagSymbol(tag, 'CanelaSidebar-linkIcon', 'fas fa-tag'), active === tag), 100 - index);
    });
    if (tags.length) {
      items.add('allTags', m(LinkButton, {
        className: "CanelaSidebar-link--all",
        href: app.route('tags'),
        icon: "fas fa-list"
      }, t('sidebar.all_tags')), -100);
    }
    return items;
  }
  tagLink(tag, icon, active) {
    return m(Link, {
      className: classList('LinkButton CanelaSidebar-tagLink', {
        active
      }),
      href: tagUrl(tag),
      active: String(active),
      title: tag.description() || undefined
    }, icon, m("span", {
      className: "Button-label"
    }, tag.name()));
  }
  footerItems() {
    const items = new ItemList();

    // A paleta à esquerda e o modo de cor, como no rodapé do Discourse.
    if (app.allowUserColorScheme) {
      items.add('palette', m(FooterPaletteSelector, null), 110);
      items.add('theme', m(FooterColorMode, null), 100);
    }

    // O "+" do rodapé, como o Discourse, só para quem está logado.
    if (app.session.user) items.add('newTopic', m(Button, {
      className: "Button Button--icon Button--flat",
      icon: "fas fa-plus",
      "aria-label": t('sidebar.new_topic'),
      title: t('sidebar.new_topic'),
      onclick: () => this.newDiscussionAction().catch(() => {})
    }), 90);
    items.add('shortcuts', m(Button, {
      className: "Button Button--icon Button--flat CanelaSidebar-footerShortcuts",
      icon: "far fa-keyboard",
      "aria-label": t('sidebar.keyboard_shortcuts'),
      title: t('sidebar.keyboard_shortcuts'),
      onclick: () => app.modal.show(() => import(/* webpackChunkName: 'forum/components/KeyboardShortcutsModal', webpackMode: 'lazy-once' */ './KeyboardShortcutsModal'))
    }), 80);
    return items;
  }
}

/** O texto de um item da barra (o rótulo do LinkButton), para a lista do "Personalizar". */
function vnodeText(node) {
  if (node == null || typeof node === 'boolean') return '';
  if (typeof node === 'string' || typeof node === 'number') return String(node);
  if (Array.isArray(node)) return node.map(vnodeText).join('');
  // O contador ao lado do rótulo (rascunhos, não lidas) não entra.
  if (typeof node.attrs?.className === 'string' && /count|suffix/i.test(node.attrs.className)) return '';
  return vnodeText(node.children ?? node.text);
}

/**
 * O menu do "Mais" abre para FORA da barra lateral: a barra rola (overflow) e
 * cortava o menu. Com position: fixed ele sai dela, colado ao botão, com uma
 * setinha apontando para o "Mais" (como um submenu), e sobe se não couber até
 * o fim da tela. No celular, é a folha que sobe do pé da tela.
 */
function placeMoreMenu() {
  requestAnimationFrame(() => {
    const toggle = document.querySelector('.CanelaSidebar-more.open .CanelaSidebar-moreButton');
    const menu = document.querySelector('.CanelaSidebar-more.open .Dropdown-menu');
    if (!toggle || !menu) return;

    // No celular o menu é a folha que sobe do pé da tela, como os outros
    // menus (o CSS do core cuida disso): sem posição calculada aqui.
    if (window.innerWidth < 768) {
      menu.classList.remove('CanelaSidebar-moreMenu--side');
      ['position', 'top', 'right', 'bottom', 'left', '--canela-more-arrow'].forEach(prop => menu.style.removeProperty(prop));
      return;
    }
    const rect = toggle.getBoundingClientRect();
    menu.classList.add('CanelaSidebar-moreMenu--side');
    menu.style.position = 'fixed';
    menu.style.right = 'auto';
    menu.style.bottom = 'auto';
    menu.style.top = '0px';
    menu.style.left = `${rect.right + 10}px`;
    const height = menu.offsetHeight;
    const wanted = rect.top + rect.height / 2 - 22;
    const top = Math.max(8, Math.min(wanted, window.innerHeight - height - 8));
    menu.style.top = `${top}px`;
    // A setinha fica na altura do meio do botão, mesmo que o menu tenha subido.
    menu.style.setProperty('--canela-more-arrow', `${rect.top + rect.height / 2 - top}px`);
  });
}
flarum.reg.add('ramon-canela', 'forum/components/CanelaSidebar', CanelaSidebar);flarum.reg.addChunkModule('forum/components/SidebarCustomizeModal', './src/forum/components/SidebarCustomizeModal.tsx', 'ramon-canela', 'forum/components/SidebarCustomizeModal');
flarum.reg.addChunkModule('forum/components/KeyboardShortcutsModal', './src/forum/components/KeyboardShortcutsModal.tsx', 'ramon-canela', 'forum/components/KeyboardShortcutsModal');
flarum.reg.addChunkModule('forum/components/CommunityCustomizeModal', './src/forum/components/CommunityCustomizeModal.tsx', 'ramon-canela', 'forum/components/CommunityCustomizeModal');